    def getDeviceValues(self):
        self.DeviceValues['time']=int(time()*1000)
        return self.DeviceValues

  
    def getValues(self):
        return self.values


    def decode(self,bytes):
        payload = {}
        
        # PanelID MeterID Node
        payload.update(self.getDeviceValues())

        # all values
        for item in self.getValues():
            if(item['length'] == 0):
                payload[item['key']]=0
            
            elif(item['length'] == 1):
                numbytes = bytes[item["position"]-1].to_bytes(2, 'big')
                payload[item['key']] = struct.unpack('>h',numbytes)[0] /item["remark"]
            elif(item['length'] == 2):
                low_byte = bytes[item["position"]-1].to_bytes(2, 'big')
                high_byte  = bytes[item["position"]].to_bytes(2, 'big')
                value = struct.unpack('>i', high_byte+low_byte)[0]
                payload[item['key']] = value /item["remark"]
            payload[item['key']]= abs(payload[item['key']]) # doing abs

        for key,ops in self.getSummingValues().items():
            #print(key,ops)
            if('PF'in key or 'V'in key ):
                ti= sum([payload[k] if k in payload else 0 for k in ops[1]])
                payload[key] = round( sum([payload[ops[0][k]]*payload[ops[1][k]] 
                if ops[0][k] in payload  and ops[1][k]  in payload else 0
                for k in range(len(ops[0])) ])/ ti if ti !=0 else (0 if 'PF'in key else sum([payload[k] if k in payload else 0 for k in ops[0]])/3 )   ,( 4 if 'PF'in key else 1))
            
            else:
                payload[key] = round(sum([payload[k] if k in payload else 0 for k in ops]), 4)
            
                



        payload['V']=round((payload['AV']*payload['Ia'] +payload['BV']*payload['Ib']+payload['CV']*payload['Ic'] )/payload['TI'] if payload['TI'] !=0 else (payload['AV']+payload['BV']+payload['CV'])/3,3  )

        #print(payload)
        return payload
        #return self.doIgnoringCTS(payload)




